import{c as e,U as t,j as o,m as i}from"./chunks/framework.DQFmIr4R.js";const f=JSON.parse('{"title":"边界情况处理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/implementation/edge-cases.md","filePath":"zh/implementation/edge-cases.md","lastUpdated":0}'),r={name:"zh/implementation/edge-cases.md"};function s(d,a,n,l,h,c){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="边界情况处理" tabindex="-1">边界情况处理 <a class="header-anchor" href="#边界情况处理" aria-label="Permalink to “边界情况处理”">​</a></h1><h2 id="空目录" tabindex="-1">空目录 <a class="header-anchor" href="#空目录" aria-label="Permalink to “空目录”">​</a></h2><ul><li><strong>打包</strong>：允许打包空目录，生成仅含头部 + 压缩后的空载荷的 <code>.ttp</code> 文件</li><li><strong>解包</strong>：输出空目录（无文件）</li></ul><h2 id="无子文件夹的目录" tabindex="-1">无子文件夹的目录 <a class="header-anchor" href="#无子文件夹的目录" aria-label="Permalink to “无子文件夹的目录”">​</a></h2><p>自动降级为扁平模式，即使未指定 <code>--flat</code>。</p><h2 id="文件数量-65535" tabindex="-1">文件数量 &gt; 65535 <a class="header-anchor" href="#文件数量-65535" aria-label="Permalink to “文件数量 &gt; 65535”">​</a></h2><p>扁平模式下必须启用 ExtInfo（自动检测或 <code>--ext-info</code> 强制），使用 uint64 文件数字段。</p><h2 id="单文件-≥-4-gib" tabindex="-1">单文件 ≥ 4 GiB <a class="header-anchor" href="#单文件-≥-4-gib" aria-label="Permalink to “单文件 ≥ 4 GiB”">​</a></h2><p>扁平模式下必须启用 ExtInfo，使用 ZIP64 式扩展长度字段。</p><h2 id="超大文件-4-gib-2-63-1" tabindex="-1">超大文件（4 GiB ~ 2^63 - 1） <a class="header-anchor" href="#超大文件-4-gib-2-63-1" aria-label="Permalink to “超大文件（4 GiB ~ 2^63 - 1）”">​</a></h2><p>目录树模式下 offset/size 以 <strong>字符串</strong> 形式存储于 JSON 中，不受 JSON Number 精度限制。</p><h2 id="文件名为空或包含特殊字符" tabindex="-1">文件名为空或包含特殊字符 <a class="header-anchor" href="#文件名为空或包含特殊字符" aria-label="Permalink to “文件名为空或包含特殊字符”">​</a></h2><p>文件名以 UTF-8 字节存储，无额外转义。实现应支持任意 Unicode 字符，但不应包含 <code>\\0</code>。</p><h2 id="中段分卷缺失" tabindex="-1">中段分卷缺失 <a class="header-anchor" href="#中段分卷缺失" aria-label="Permalink to “中段分卷缺失”">​</a></h2><p>扫描分卷时发现断层（如 001、002、004 存在，003 缺失），当前行为是静默停止于缺失处。解包器应警告预期卷数与实际卷数不匹配。</p><h2 id="自定义数据段缺失-hascustom-1-但数据不存在或长度不足" tabindex="-1">自定义数据段缺失（HasCustom=1 但数据不存在或长度不足） <a class="header-anchor" href="#自定义数据段缺失-hascustom-1-但数据不存在或长度不足" aria-label="Permalink to “自定义数据段缺失（HasCustom=1 但数据不存在或长度不足）”">​</a></h2><p>解包器应检测到载荷长度不足并报错，避免越界读取。</p><h2 id="压缩流损坏" tabindex="-1">压缩流损坏 <a class="header-anchor" href="#压缩流损坏" aria-label="Permalink to “压缩流损坏”">​</a></h2><p>解压时如果数据损坏，相应的解压函数应抛出异常，解包器捕获后报错退出。</p><h2 id="目录树模式下-offset-size-字符串格式" tabindex="-1">目录树模式下 offset/size 字符串格式 <a class="header-anchor" href="#目录树模式下-offset-size-字符串格式" aria-label="Permalink to “目录树模式下 offset/size 字符串格式”">​</a></h2><p>JSON 中的 <code>&quot;o&quot;</code> 和 <code>&quot;s&quot;</code> 为十进制数字字符串（如 <code>&quot;21474836480&quot;</code>），解包时需 <code>int()</code> / <code>parseInt()</code> 转换为整数。</p>',21)])])}const m=e(r,[["render",s]]);export{f as __pageData,m as default};
